<?php
namespace Tests\Feature;
use App\Models\KnowledgeDocument;use App\Models\Purok;use App\Models\Report;use App\Models\ReportCategory;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class CompleteWorkflowTest extends TestCase {use RefreshDatabase;
 protected function setUp():void{parent::setUp();$this->seed();}
 public function test_admin_can_manage_content_and_index_approved_knowledge():void{$admin=User::factory()->create(['role'=>'admin','status'=>'active']);$this->actingAs($admin)->get(route('admin.advisories.index'))->assertOk();$this->actingAs($admin)->post(route('admin.advisories.store'),['title'=>'Water interruption','type'=>'advisory','summary'=>'Scheduled maintenance','content'=>'Water service will be unavailable from 8 AM to noon.','audience'=>'everyone','status'=>'published'])->assertRedirect();$this->assertDatabaseHas('advisories',['title'=>'Water interruption','status'=>'published']);$this->actingAs($admin)->post(route('admin.knowledge.store'),['title'=>'Barangay service guide','source_type'=>'faq','content'=>'Barangay clearance applications are accepted at the barangay office on weekdays.','is_approved'=>1])->assertRedirect();$document=KnowledgeDocument::first();$this->assertTrue($document->is_approved);$this->assertGreaterThan(0,$document->chunks()->count());}
 public function test_assigned_staff_can_update_validated_report_and_resident_can_read_history():void{$resident=User::factory()->create(['role'=>'resident','status'=>'active']);$staff=User::factory()->create(['role'=>'staff','status'=>'active']);$report=Report::create(['reference_number'=>'BF-2026-999999','resident_id'=>$resident->id,'assigned_staff_id'=>$staff->id,'category_id'=>ReportCategory::first()->id,'purok_id'=>Purok::first()->id,'title'=>'Blocked drainage','description'=>'Drainage is blocked near the road.','priority'=>'normal','status'=>'pending','validation_status'=>'validated','validated_at'=>now(),'latitude'=>6.1164,'longitude'=>125.1716]);Sanctum::actingAs($staff);$this->postJson("/api/staff/assigned-reports/{$report->id}/progress",['status'=>'in_progress','notes'=>'Inspected the drainage and started clearing work.'])->assertOk()->assertJsonPath('data.status','in_progress');Sanctum::actingAs($resident);$this->getJson("/api/resident/reports/{$report->id}")->assertOk()->assertJsonPath('data.status_histories.0.to_status','in_progress');}
 public function test_admin_map_print_and_notification_pages_render():void{$admin=User::factory()->create(['role'=>'admin','status'=>'active']);$this->actingAs($admin)->get(route('admin.reports.map'))->assertOk();$this->actingAs($admin)->get(route('admin.reports.print'))->assertOk()->assertSee('Community Report Register');$this->actingAs($admin)->get(route('admin.notifications.index'))->assertOk();}
}
